package com.nivor.journal;import java.time.LocalDate;import java.util.*;import org.springframework.data.jpa.repository.EntityGraph;import org.springframework.data.jpa.repository.JpaRepository;public interface JournalEntryRepository extends JpaRepository<JournalEntry,Long>{@EntityGraph(attributePaths="tags")List<JournalEntry> findAllByUser_IdOrderByEntryDateDesc(Long id);@EntityGraph(attributePaths="tags")List<JournalEntry> findAllByUser_IdAndEntryDate(Long id,LocalDate date);@EntityGraph(attributePaths="tags")List<JournalEntry> findAllByUser_IdAndEntryDateBetweenOrderByEntryDateDesc(Long id,LocalDate from,LocalDate to);@EntityGraph(attributePaths="tags")Optional<JournalEntry> findByIdAndUser_Id(Long id,Long userId);}
